INSERT INTO `products` (`name`, `description`, `price`, `discount`, `stock`, `image`, `category_id`, `is_featured`, `is_limited`, `is_trending`, `features`, `vendor_id`, `status`, `visibility`, `vendor_service_id`, `about`, `menifectures_images`, `detailed_description_paragraphs`) VALUES
('Wireless Bluetooth Headphones', 'Experience immersive audio with premium wireless headphones designed for music, calls, gaming and travel. Powerful drivers deliver clear vocals and rich bass, while the cushioned over-ear design helps reduce listening fatigue. Bluetooth connectivity provides convenient wireless pairing, and the rechargeable battery supports extended everyday use. The foldable design makes storage and travel simple.', 2499, 1000, 50, '[]', 1, 1, 0, 1, '{"Bluetooth Version":"5.3","Driver Size":"40mm","Battery Capacity":"500mAh","Playback Time":"Up to 40 hours","Charging Time":"Approximately 2 hours","Charging Port":"USB Type-C","Noise Cancellation":"Active noise reduction","Microphone":"Built-in","Connectivity":"Bluetooth and AUX","Color":"Matte Black"}', 2, 'active', 'public', '[]', '["Rich bass and clear audio for music, movies and calls.","Comfortable cushioned ear cups for extended listening.","Foldable design makes storage and travel convenient.","Wireless Bluetooth connection pairs with compatible devices.","Built-in microphone supports hands-free conversations."]', '[]', '["Enjoy music, movies and calls with balanced audio designed for everyday entertainment.","The over-ear cushions and adjustable headband provide a comfortable fit during longer listening sessions.","Wireless Bluetooth connectivity helps you move freely without dealing with tangled cables.","A rechargeable battery provides extended playback, while USB Type-C makes charging convenient.","The foldable design and lightweight construction make these headphones a practical companion at home or on the go."]'),
('Smart Fitness Watch', 'Track your everyday activity with a stylish smartwatch featuring a bright touchscreen, activity tracking and convenient phone notifications. Its lightweight body and adjustable strap are designed for daily comfort. Use the watch to view activity information, monitor workout sessions and stay connected while commuting, working or exercising.', 3199, 1300, 35, '[]', 2, 1, 0, 1, '{"Display Size":"1.85 inches","Display Type":"HD touchscreen","Resolution":"240 x 280 pixels","Battery Capacity":"300mAh","Battery Life":"Up to 7 days (usage dependent)","Charging":"Magnetic charging cable","Activity Tracking":"Steps and calories","Health Features":"Heart-rate and sleep tracking","Strap Material":"Silicone","Color":"Black"}', 2, 'active', 'public', '[]', '["Large touchscreen makes menus and notifications easy to view.","Track daily steps, calories and workout activity.","Heart-rate and sleep tracking features support activity awareness.","Lightweight body and adjustable strap are comfortable for daily wear.","Receive compatible smartphone notifications on your wrist."]', '[]', '["Bring useful everyday information to your wrist with this modern fitness smartwatch.","The large touchscreen provides a convenient way to view the time, activity information and supported notifications.","Activity tracking features help you review steps, calories and workout sessions throughout the day.","Its lightweight body and adjustable silicone strap are designed for comfortable everyday use.","Recharge the watch with the included magnetic cable and connect it to a compatible smartphone for supported smart features."]'),
('Men''s Casual Sneakers', 'Refresh your everyday wardrobe with casual sneakers that combine a versatile look and practical comfort. The breathable upper, cushioned footbed and lightweight construction make them suitable for walking, college, commuting and relaxed outings. A durable rubber outsole provides everyday grip, while the lace-up design allows an adjustable fit.', 1799, 700, 75, '[]', 3, 0, 1, 1, '{"Product Type":"Casual sneakers","Gender":"Men","Upper Material":"Synthetic leather and textile","Sole Material":"Rubber","Closure":"Lace-up","Shoe Style":"Low-top","Color":"Black and white","Pattern":"Color-block","Footbed":"Cushioned","Available Sizes":"UK 6, 7, 8, 9, 10"}', 3, 'active', 'public', '[]', '["Versatile casual style for everyday outfits.","Breathable upper helps improve airflow.","Cushioned footbed supports comfortable walking.","Rubber outsole provides everyday traction.","Lace-up closure allows an adjustable fit."]', '[]', '["Add a clean casual look to your wardrobe with sneakers designed for everyday use.","The combination of synthetic material and textile panels creates a versatile upper suitable for regular outings.","A cushioned footbed helps provide comfort while walking, commuting or spending time on campus.","The rubber outsole is designed to provide dependable everyday grip on common walking surfaces.","Pair these low-top lace-up sneakers with jeans, joggers or casual clothing for a relaxed style."]'),
('Premium Laptop Backpack', 'Carry your laptop and daily essentials in an organized backpack designed for students, professionals and commuters. A padded laptop compartment, multiple storage pockets and adjustable shoulder straps help make everyday carrying convenient. The polyester exterior is designed for regular use, while the clean design works well for college, office and travel.', 1299, 700, 100, '[]', 4, 1, 0, 0, '{"Material":"Polyester","Capacity":"25 litres","Laptop Compatibility":"Up to 15.6 inches","Main Compartment":"1","Front Pockets":"2","Side Pockets":"2","Shoulder Straps":"Adjustable and padded","Back Panel":"Padded","Closure":"Zipper","Color":"Black"}', 3, 'active', 'public', '[]', '["Padded compartment accommodates compatible laptops up to 15.6 inches.","Multiple pockets help organize accessories and essentials.","Adjustable padded straps support comfortable carrying.","Lightweight design is suitable for daily commuting.","Minimal appearance works for college, office and travel."]', '[]', '["Keep your everyday essentials organized with a practical backpack designed for busy routines.","The dedicated padded compartment helps separate and protect a compatible laptop during everyday travel.","Additional pockets provide space for chargers, notebooks, stationery, bottles and other small accessories.","Adjustable shoulder straps and a padded back panel are designed to make carrying more comfortable.","Its simple black design makes the backpack suitable for college, office, commuting and short trips."]'),
('Mechanical Gaming Keyboard', 'Improve your desktop setup with a full-size mechanical keyboard designed for gaming, coding and everyday typing. Responsive switches provide tactile feedback, while RGB backlighting adds customizable style to your desk. Anti-ghosting support helps register multiple key presses, and the wired USB connection offers straightforward plug-and-play setup on compatible computers.', 2899, 1100, 25, '[]', 5, 1, 1, 1, '{"Keyboard Type":"Mechanical","Switch Type":"Blue tactile switches","Layout":"Full size","Number of Keys":"104","Connection":"Wired USB","Lighting":"RGB backlighting","Anti-Ghosting":"Supported","Cable Length":"1.8 metres","Keycap Material":"ABS","Compatibility":"Windows, macOS and Linux"}', 2, 'active', 'public', '[]', '["Tactile mechanical switches provide responsive typing feedback.","RGB backlighting adds visual style to a gaming setup.","Anti-ghosting supports multiple simultaneous key presses.","Full-size layout includes a dedicated number pad.","Wired USB connection offers simple plug-and-play setup."]', '[]', '["Create a responsive desktop setup with a mechanical keyboard suited to gaming and productivity.","The tactile switches provide noticeable feedback for typing, programming and supported games.","RGB backlighting gives the keyboard a distinctive appearance and helps illuminate the keys in dim environments.","Anti-ghosting support helps register multiple key presses when several keys are used together.","Connect the keyboard through its wired USB cable to a compatible computer for straightforward setup."]'),
('Portable Bluetooth Speaker', 'Enjoy portable audio at home, outdoors or while travelling with a compact Bluetooth speaker. It pairs wirelessly with compatible phones, tablets and laptops, and its rechargeable battery supports music playback away from a power outlet. Simple controls make it easy to manage playback and volume, while the compact design fits easily into a bag.', 1599, 400, 60, '[]', 1, 0, 0, 1, '{"Bluetooth Version":"5.2","Output Power":"10W","Battery Capacity":"2000mAh","Playback Time":"Up to 8 hours","Charging Port":"USB Type-C","Audio Input":"Bluetooth and AUX","Microphone":"Built-in hands-free mic","Controls":"Physical buttons","Design":"Portable compact body","Color":"Navy Blue"}', 2, 'active', 'public', '[]', '["Compact speaker for home listening and travel.","Wireless pairing with compatible devices.","Rechargeable battery supports portable playback.","Simple buttons control volume and playback.","AUX input provides an additional connection option."]', '[]', '["Take your music with you using a compact speaker designed for convenient everyday listening.","Pair a compatible phone, tablet or laptop over Bluetooth and play audio without a wired connection.","The rechargeable battery supports portable listening when a wall outlet is not available.","Easy-to-reach buttons help you adjust volume and control playback without opening your device.","Its compact shape fits conveniently on a desk, shelf or inside a travel bag."]'),
('Stainless Steel Water Bottle', 'Stay hydrated throughout the day with a reusable stainless steel water bottle. Its practical capacity makes it suitable for office, college, gym sessions and travel. The screw-top lid helps prevent spills when properly closed, and the reusable design offers a convenient alternative to disposable drink bottles.', 699, 150, 120, '[]', 6, 0, 0, 0, '{"Capacity":"750ml","Material":"Stainless steel","Lid Type":"Screw-top","Insulation":"Double-wall design","Finish":"Matte","Bottle Shape":"Slim cylindrical","Leak Protection":"Sealed lid when closed correctly","Care":"Hand wash recommended","Reusable":"Yes","Color":"Silver"}', 3, 'active', 'public', '[]', '["Reusable bottle for everyday hydration.","Stainless steel body is suitable for regular use.","750ml capacity works for work, study and exercise.","Screw-top lid helps reduce accidental spills.","Slim shape fits many standard backpack side pockets."]', '[]', '["Make daily hydration easier with a reusable stainless steel bottle for work, study and travel.","The 750ml capacity provides room for water or your preferred cold beverage throughout the day.","A screw-top lid helps keep the bottle closed during normal carrying when secured correctly.","The slim design is convenient to hold and can fit many standard backpack side pockets.","Clean the bottle regularly according to the care instructions to keep it ready for repeated use."]'),
('Men''s Classic Analog Watch', 'Complete your everyday look with a classic analog wristwatch featuring a clean dial and comfortable strap. Its versatile styling is suitable for office wear, casual occasions and everyday use. The easy-to-read hands and simple time display make it a practical accessory for daily routines.', 1899, 500, 40, '[]', 7, 1, 0, 0, '{"Display":"Analog","Movement":"Quartz","Dial Shape":"Round","Strap Material":"Stainless steel","Case Material":"Alloy","Dial Color":"Black","Strap Color":"Silver","Clasp":"Fold-over clasp","Water Resistance":"Basic splash resistance","Style":"Classic"}', 2, 'active', 'public', '[]', '["Classic styling suits formal and casual outfits.","Quartz movement provides convenient timekeeping.","Easy-to-read analog dial with clear markers.","Metal strap offers a polished appearance.","Suitable for everyday wear and gifting."]', '[]', '["Add a timeless accessory to your collection with this classic analog wristwatch.","The round dial and clear markers make it easy to check the time throughout the day.","Quartz movement offers convenient everyday timekeeping with routine battery replacement as required.","The metal strap and understated styling pair well with office clothing and casual outfits.","Use the watch as an everyday accessory or as a thoughtful gift for a special occasion."]'),
('Wireless Optical Mouse', 'Work and browse comfortably with a wireless optical mouse designed for everyday computer use. Its compact shape, responsive sensor and simple wireless receiver make it suitable for desktops and laptops. The ergonomic body fits naturally in the hand, while convenient buttons support common navigation tasks.', 599, 100, 90, '[]', 5, 0, 0, 1, '{"Connection":"2.4GHz wireless","DPI":"1600 DPI","Sensor":"Optical","Buttons":"3","Receiver":"USB nano receiver","Power":"1 AA battery","Compatibility":"Windows, macOS and Linux","Design":"Ambidextrous","Range":"Up to 10 metres (environment dependent)","Color":"Black"}', 2, 'active', 'public', '[]', '["Wireless operation helps reduce desk cable clutter.","Optical sensor supports everyday navigation.","Compact shape is convenient for travel and laptop bags.","USB nano receiver provides simple connection.","Suitable for study, office and home computer use."]', '[]', '["Navigate your computer comfortably with a practical wireless optical mouse.","The 2.4GHz wireless connection uses a compact USB receiver for convenient setup on compatible computers.","Its optical sensor is designed for smooth everyday browsing, document work and general productivity.","The compact body is easy to carry with a laptop and helps keep your workspace tidy.","Connect the receiver, insert the required battery and use the mouse with a compatible operating system."]'),
('LED Desk Study Lamp', 'Brighten your workspace with an LED desk lamp designed for reading, studying and computer work. Its adjustable structure helps direct light where needed, while touch controls make brightness adjustments convenient. The compact base fits neatly on a desk, bedside table or study corner.', 999, 250, 55, '[]', 8, 1, 0, 0, '{"Light Source":"LED","Brightness Modes":"3 levels","Color Temperature":"Adjustable modes","Control":"Touch control","Power Source":"USB powered","Adjustability":"Flexible lamp neck","Base":"Stable non-slip base","Usage":"Study and desk lighting","Color":"White","Energy Use":"Low-power LED"}', 3, 'active', 'public', '[]', '["Useful for reading, studying and desk work.","Adjustable neck helps direct light onto the work area.","Touch control makes brightness changes simple.","Compact base fits common desk spaces.","LED lighting is designed for energy-efficient operation."]', '[]', '["Create a comfortable study or work area with a compact LED desk lamp.","The adjustable lamp neck helps position light over books, documents or a keyboard as needed.","Touch controls provide a convenient way to switch the lamp on and adjust supported brightness settings.","Its stable base is designed to sit neatly on a desk, bedside table or study surface.","Connect the lamp to a compatible USB power source and position it to suit your workspace."]'),
('Ceramic Coffee Mug Set', 'Enjoy tea, coffee and other hot beverages with a set of ceramic mugs designed for everyday home and office use. The smooth glazed finish gives the mugs a clean appearance, while the comfortable handles make them easy to hold. The set is suitable for daily use, entertaining guests or gifting.', 799, 200, 70, '[]', 9, 0, 0, 0, '{"Set Contains":"2 mugs","Material":"Ceramic","Capacity":"300ml each","Finish":"Glossy glazed","Shape":"Round","Handle":"Easy-grip handle","Use":"Tea, coffee and beverages","Care":"Hand wash recommended","Microwave Use":"Check product care label","Color":"White"}', 3, 'active', 'public', '[]', '["Two-piece set for home or office use.","300ml capacity for tea, coffee and other beverages.","Ceramic construction with a smooth glazed finish.","Comfortable handles make the mugs easy to hold.","Suitable for everyday use or gifting."]', '[]', '["Serve your favourite hot beverages in this simple ceramic coffee mug set.","Each mug offers a 300ml capacity suitable for tea, coffee and other everyday drinks.","The smooth glazed finish gives the mugs a clean appearance that fits many kitchen styles.","Comfortable handles make each mug easy to hold while enjoying a drink at home or in the office.","Follow the care label for cleaning and guidance on microwave use."]'),
('Yoga Exercise Mat', 'Support your home workouts with a lightweight exercise mat suitable for yoga, stretching and floor exercises. The textured surface is designed to provide grip during common movements, while the cushioned construction adds comfort between your body and the floor. It rolls up for convenient storage after a workout.', 899, 200, 65, '[]', 10, 0, 1, 1, '{"Length":"183cm","Width":"61cm","Thickness":"6mm","Material":"TPE foam","Surface":"Textured","Use":"Yoga and floor exercise","Portability":"Roll-up design","Cleaning":"Wipe with damp cloth","Color":"Purple","Included":"Carry strap"}', 3, 'active', 'public', '[]', '["Suitable for yoga, stretching and home workouts.","Cushioned surface adds comfort during floor exercises.","Textured finish is designed to support grip.","Lightweight roll-up design makes storage convenient.","Easy to clean after regular exercise sessions."]', '[]', '["Create a dedicated workout space at home with this lightweight exercise mat.","Its cushioned surface provides a comfortable layer between your body and the floor during stretching and floor exercises.","The textured finish is designed to support grip during common yoga movements when used on a clean, dry surface.","After your workout, roll the mat up and secure it for convenient storage or transport.","Wipe the mat with a damp cloth and allow it to dry fully before storing."]'),
('Travel Trolley Suitcase', 'Travel with your essentials organized in a practical trolley suitcase designed for holidays and business trips. The spacious main compartment provides room for clothing and accessories, while internal straps help keep packed items in place. Smooth-rolling wheels and a telescopic handle make it easier to move through airports, stations and hotels.', 3499, 800, 30, '[]', 11, 1, 1, 0, '{"Capacity":"55 litres","Material":"ABS hard shell","Wheels":"4 spinner wheels","Handle":"Telescopic handle","Lock":"Combination lock","Compartments":"Main compartment with divider","Closure":"Zipper","Interior":"Packing straps","Color":"Navy Blue","Use":"Travel and business trips"}', 2, 'active', 'public', '[]', '["Spacious interior for clothing and travel essentials.","Hard-shell exterior helps protect packed belongings.","Four spinner wheels support easy movement.","Telescopic handle adjusts for convenient pulling.","Internal straps help keep items organized."]', '[]', '["Organize your belongings for holidays and business trips with this practical trolley suitcase.","The spacious main compartment provides room for clothing, toiletries and travel accessories.","A hard-shell exterior helps shield packed items from everyday handling during travel.","Four spinner wheels and a telescopic handle make the suitcase easier to move through terminals and hotels.","Use the internal divider and packing straps to arrange your belongings before closing the zipper."]'),
('Portable Power Bank 20000mAh', 'Keep compatible devices powered while travelling or away from a wall outlet with this high-capacity portable power bank. Its compact design is convenient to carry in a backpack, and multiple output ports allow supported devices to be charged. LED indicators help show the remaining battery level so you can plan when to recharge the power bank.', 1999, 500, 45, '[]', 1, 1, 0, 1, '{"Capacity":"20000mAh","Input":"USB Type-C","Output":"USB-A and USB Type-C","Ports":"2 output ports","Indicator":"LED battery indicators","Charging":"Fast charging support (device dependent)","Protection":"Over-current and short-circuit protection","Compatibility":"Supported USB devices","Color":"Black","Included":"Charging cable"}', 2, 'active', 'public', '[]', '["High capacity for charging compatible devices on the go.","Multiple output ports support convenient charging.","LED indicators show approximate remaining battery level.","Portable design fits easily in a travel bag.","Built-in protection features support safer operation."]', '[]', '["Stay prepared while travelling with a portable power bank designed to recharge compatible USB devices.","Its 20000mAh rated capacity provides additional power when a wall outlet is not readily available.","USB output ports let you connect supported phones, earbuds and other small electronic devices.","LED indicators provide a quick view of the remaining battery level before you head out.","Recharge the power bank using a compatible USB Type-C charger and follow the device instructions for safe use."]'),
('Adjustable Laptop Stand', 'Improve your desk setup with an adjustable laptop stand designed to raise a compatible laptop to a more convenient viewing position. Its foldable structure supports easy storage, while the open design allows airflow around the device. Use it at a home office, study desk or shared workspace.', 1199, 300, 80, '[]', 5, 0, 0, 1, '{"Material":"Aluminium alloy","Compatibility":"Laptops up to 15.6 inches","Adjustment":"Multiple height and angle positions","Design":"Foldable","Base":"Anti-slip pads","Laptop Support":"Silicone protective pads","Ventilation":"Open-frame design","Color":"Space Grey","Use":"Desk and home office","Portability":"Portable lightweight structure"}', 3, 'active', 'public', '[]', '["Raises a laptop to a more convenient viewing height.","Adjustable positions support different desk setups.","Foldable design makes storage and transport easy.","Anti-slip pads help keep the stand stable.","Open structure allows airflow around the laptop."]', '[]', '["Create a more organized workspace with an adjustable laptop stand for home, office or study use.","The stand raises a compatible laptop and offers multiple angle positions to suit different desk arrangements.","Protective pads help cushion contact points and reduce unwanted movement during normal use.","Its open-frame design leaves space around the laptop to support airflow while working.","Fold the stand when it is not needed and store it in a desk drawer or carry bag."]');
